	@Test
	void publicDatasetLookupsSkipDisjointPagesForEveryRequestedContext(@TempDir File dataDir) throws Exception {
		var values = SimpleValueFactory.getInstance();
		IRI subject = values.createIRI("urn:subject");
		IRI predicate = values.createIRI("urn:predicate");
		IRI object = values.createIRI("urn:object");
		IRI graph = values.createIRI("urn:graph");
		IRI otherGraph = values.createIRI("urn:other-graph");
		IRI absentGraph = values.createIRI("urn:absent-graph");
		LmdbStore sail = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyCoverage(DirectAdjacencyCoverage.FULL)
				.setDirectAdjacencyMaxBytes(1L << 30));
		SailRepository repository = new SailRepository(sail);
		repository.init();
		try {
			try (var connection = repository.getConnection()) {
				connection.add(subject, predicate, object, graph);
				connection.add(values.createIRI("urn:other-subject"), values.createIRI("urn:other-predicate"),
						object, otherGraph);
			}
			LmdbDirectAdjacencyStore direct = sail.getBackingStore().directAdjacencyStore();
			direct.awaitCommitCleanupForTest();
			direct.awaitCompactionForTest();
			assertThat(direct.buildNowForTest()).isTrue();
			try (var dataset = sail.getBackingStore().getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT)) {
				long before = CsfPageTestAccess.decodes();
				try (var rows = dataset.getStatements(subject, predicate, null, null, otherGraph, absentGraph)) {
					assertThat(rows.hasNext()).isFalse();
				}
				try (var rows = dataset.getStatements(StatementOrder.O, subject, predicate, null,
						null, otherGraph, absentGraph)) {
					assertThat(rows.hasNext()).isFalse();
				}
				assertThat(dataset.hasStatements(subject, predicate, null, null, otherGraph, absentGraph)).isFalse();
				assertThat(CsfPageTestAccess.decodes() - before)
						.as("public lookup planning and execution must both preserve page context pruning")
						.isZero();

				Statement expected = values.createStatement(subject, predicate, object, graph);
				for (Resource[] contexts : new Resource[][] { {}, { null, graph },
						{ otherGraph, graph, absentGraph } }) {
					try (var rows = dataset.getStatements(subject, predicate, null, contexts)) {
						assertThat(rows.hasNext()).isTrue();
						assertThat(rows.next()).isEqualTo(expected);
						assertThat(rows.hasNext()).isFalse();
					}
					try (var rows = dataset.getStatements(StatementOrder.O, subject, predicate, null, contexts)) {
						assertThat(rows.hasNext()).isTrue();
						assertThat(rows.next()).isEqualTo(expected);
						assertThat(rows.hasNext()).isFalse();
					}
					assertThat(dataset.hasStatements(subject, predicate, null, contexts)).isTrue();
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void everyBoundAndRootProviderSkipsDisjointPagesForNextFillAndExistence(@TempDir File dataDir)
			throws Exception {
		try (Fixture fixture = new Fixture(dataDir)) {
			fixture.seed();
			try (LmdbAdjacencyReadView view = fixture.adjacency.acquire(fixture.triples.getDataRevision())) {
				for (boolean explicit : new boolean[] { true, false }) {
					for (long[] pattern : new long[][] { { S, P, -1 }, { -1, P, O }, { S, P, O }, { -1, P, -1 } }) {
						long s = pattern[0];
						long p = pattern[1];
						long o = pattern[2];
						for (long context : new long[] { 0, G2, uri(999) }) {
							assertEmptyWithoutDecodes(() -> fixture.adjacency.tryOpen(view, null, s, p, o, context,
									explicit));
							for (StatementOrder order : StatementOrder.values()) {
								assertEmptyWithoutDecodes(() -> fixture.adjacency.tryOpenUniversal(view, order, s, p, o,
										context, explicit));
								if (order != StatementOrder.P || s > 0 || o > 0) {
									assertEmptyWithoutDecodes(
											() -> fixture.adjacency.tryOpenOrdered(view, null, order, s,
													p, o, context, explicit));
								}
							}
							assertEmptyWithoutDecodes(() -> fixture.adjacency.tryOpenRange(view,
									new LmdbKeyRange(null, null, "spoc"), s, p, o, context, explicit));
							long before = CsfPageTestAccess.decodes();
							assertThat(fixture.adjacency.tryHas(view, s, p, o, context, explicit)).isZero();
							assertThat(fixture.adjacency.tryCount(view, s, p, o, context, explicit)).isZero();
							assertThat(CsfPageTestAccess.decodes() - before)
									.as("existence and count must reject the page before binding")
									.isZero();
						}
					}
				}
			}
		}
	}

	@Test
	void mixedDefaultNamedAndWildcardContextsPreserveEveryBindingMask(@TempDir File dataDir) throws Exception {
		try (Fixture fixture = new Fixture(dataDir)) {
			fixture.seed();
			fixture.triples.startTransaction();
			for (boolean explicit : new boolean[] { true, false }) {
				fixture.triples.storeTriple(S, P, O, 0L, explicit);
				fixture.triples.storeTriple(S, P, O, G2, explicit);
				fixture.triples.storeTriple(uri(3), P, uri(203), G1, explicit);
			}
			fixture.commit();
			assertThat(fixture.adjacency.buildNowForTest()).isTrue();
			List<List<Long>> all = List.of(List.of(S, P, O, 0L), List.of(S, P, O, G1), List.of(S, P, O, G2),
					List.of(uri(3), P, uri(203), G1), List.of(uri(2), uri(102), uri(202), G2));
			try (LmdbAdjacencyReadView view = fixture.adjacency.acquire(fixture.triples.getDataRevision())) {
				long before = CsfPageTestAccess.decodes();
				for (boolean explicit : new boolean[] { true, false }) {
					for (int mask = 0; mask < 8; mask++) {
						long s = (mask & 1) == 0 ? -1L : S;
						long p = (mask & 2) == 0 ? -1L : P;
						long o = (mask & 4) == 0 ? -1L : O;
						for (long context : new long[] { -1, 0, G1, G2, uri(999) }) {
							List<List<Long>> expected = all.stream()
									.filter(row -> s < 0 || row.get(0) == s)
									.filter(row -> p < 0 || row.get(1) == p)
									.filter(row -> o < 0 || row.get(2) == o)
									.filter(row -> context < 0 || row.get(3) == context)
									.toList();
							assertThat(rows(fixture.adjacency.tryOpen(view, null, s, p, o, context, explicit), false))
									.containsExactlyInAnyOrderElementsOf(expected);
							for (StatementOrder order : StatementOrder.values()) {
								assertThat(rows(
										fixture.adjacency.tryOpenUniversal(view, order, s, p, o, context, explicit),
										true)).containsExactlyInAnyOrderElementsOf(expected);
							}
							int exists = fixture.adjacency.tryHas(view, s, p, o, context, explicit);
							if (exists >= 0) {
								assertThat(exists).isEqualTo(expected.isEmpty() ? 0 : 1);
							}
						}
					}
				}
				assertThat(CsfPageTestAccess.decodes() - before)
						.as("matching and mixed pages must still be materialized")
						.isPositive();
			}
		}
	}

